def _deep_copy(value):
    """Return an object equal to ``value`` that shares no mutable state with it."""
    if isinstance(value, dict):
        return {k: _deep_copy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_copy(v) for v in value]
    if isinstance(value, tuple):
        return tuple(_deep_copy(v) for v in value)
    if isinstance(value, set):
        return {_deep_copy(v) for v in value}
    if isinstance(value, frozenset):
        return frozenset(_deep_copy(v) for v in value)
    return value  # scalars (None, bool, int, float, str, ...) are immutable


def _merge_into(target, override):
    """Fold ``override`` into ``target`` (mutating ``target`` in place)."""
    for key, value in override.items():
        if value is None:
            # A ``None`` override value removes the key (a no-op if absent).
            target.pop(key, None)
        elif isinstance(value, dict):
            existing = target.get(key)
            if isinstance(existing, dict):
                _merge_into(existing, value)
            else:
                target[key] = _deep_copy(value)
        else:
            # Lists, scalars, and type-mismatched values are replaced, never merged.
            target[key] = _deep_copy(value)


def merge(base: dict, override: dict) -> dict:
    """Deep-merge ``override`` onto ``base`` and return a new dict.

    Rules:
      * Nested dicts are merged recursively.
      * Lists and scalars from ``override`` replace those from ``base``
        (lists are never concatenated).
      * A key whose value in ``override`` is ``None`` is removed from the
        result, even when it is absent from ``base``.
      * Neither input is modified, and the result shares no mutable
        objects with either input.

    Raises:
        ValueError: if ``base`` or ``override`` is not a ``dict``.
    """
    if not isinstance(base, dict) or not isinstance(override, dict):
        raise ValueError("both base and override must be dicts")

    result = _deep_copy(base)
    _merge_into(result, override)
    return result
